public class ProbeSuppressedPrivateTests
{
    [Fact]
    public async Task AllowPrivateRequiredIsReportedForSuppressedType()
    {
        string input = @"
using MessagePack;

[{|MsgPack015:MessagePackObject(SuppressSourceGeneration = true)|}]
public class Foo
{
    [Key(0)]
    private string member;
}
";
        await new VerifyCS.Test { TestCode = input, MarkupOptions = MarkupOptions.UseFirstDescriptor }.RunAsync();
    }
}

